async function loadForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  assertOrgScope(actor, orgId);
  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return { milestone, project };
}

async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const wanted = normalizeName(name);
  const existing = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  if (
    existing.some(
      (m) => m.id !== exceptId && normalizeName(m.name) === wanted,
    )
  ) {
    throw new MilestoneStateError("name_taken", `Milestone "${name}" already exists`);
  }
}

async function assertRoomForOpen(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const existing = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const open = existing.filter((m) => m.closedAt === null).length;
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError(
      "too_many_open",
      `A project may hold at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`,
    );
  }
}

async function withProgress(
  milestone: Milestone,
  now: Date,
): Promise<MilestoneWithProgress> {
  const progress = await milestoneRepo.getMilestoneProgress(
    milestone.orgId,
    milestone.id,
  );
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    new Date(milestone.targetDate).getTime() < now.getTime() &&
    progress.open > 0;
  return { milestone, progress, overdue };
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name = input.name.trim();
  await assertNameFree(input.orgId, project.id, name, null);
  await assertRoomForOpen(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);

  const patch: { name?: string; targetDate?: Milestone["targetDate"] } = {};
  if (input.name !== undefined) {
    const name = input.name.trim();
    await assertNameFree(input.orgId, milestone.projectId, name, milestone.id);
    patch.name = name;
  }
  if (input.targetDate !== undefined) patch.targetDate = input.targetDate;

  if (Object.keys(patch).length === 0) return milestone;
  return milestoneRepo.updateMilestone(input.orgId, milestone.id, patch);
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed", "Milestone is already closed");
  }

  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new (await import("./_support")).NotFoundError("Milestone", targetId);
    }
    const target = await loadMilestone(input.orgId, targetId);
    if (target.projectId !== milestone.projectId) {
      throw new (await import("./_support")).NotFoundError("Milestone", targetId);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed", "Target milestone is closed");
    }
  }

  const open = await milestoneRepo.listOpenLiveIssueIds(input.orgId, milestone.id);
  const movedIssueIds = open.map((issue) => issue.id);
  await milestoneRepo.setIssuesMilestone(input.orgId, movedIssueIds, targetId);

  const closed = await milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    closedAt: actorEnvelope(actor).occurredAt,
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(actor, orgId, milestoneId);
  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open", "Milestone is already open");
  }
  await assertRoomForOpen(orgId, milestone.projectId);

  const reopened = await milestoneRepo.updateMilestone(orgId, milestone.id, {
    closedAt: null,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open first, then closed; by target date (none last); then by creation. */
function compareMilestones(a: Milestone, b: Milestone): number {
  const openA = a.closedAt === null ? 0 : 1;
  const openB = b.closedAt === null ? 0 : 1;
  if (openA !== openB) return openA - openB;
  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const diff = new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime();
    if (diff !== 0) return diff;
  }
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const rows = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);
  return Promise.all(rows.map((m) => withProgress(m, now)));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));
  return withProgress(milestone, new Date());
}
